function draw(typed = true) { const onDismiss = vi.fn(); const onOpenDocument = vi.fn(); const view = render(<EvidenceDrawer snapshot={snapshot(typed)} selection={{ figureId: selected }} onDismiss={onDismiss} onOpenDocument={onOpenDocument} renderEvidenceBadge={(grade) => <span>{grade.label}</span>} />); return { ...view, onDismiss, onOpenDocument }; }
describe("supported typed figure evidence", () => {
  it("uses the actual quantity/date and meaningful limitations without contradictory legacy absence placeholders", () => {
    const view = draw();
    for (const text of ["Measurement type was not supplied by this read.", "Exactness unavailable", "Coverage was not supplied by this read.", "Provenance details were not supplied by this read."]) expect(view.queryByText(text)).toBeNull();
    expect(view.getByRole("heading", { name: "Figure details" })).toBeVisible(); expect(view.queryByRole("heading", { name: "Typed numerical figure" })).toBeNull();
    expect(view.container.querySelector('[data-field="quantity"]')).toHaveTextContent("Balance"); expect(view.container.querySelector('[data-field="dated"]')).toHaveTextContent("2026-01-31");
    expect(view.getByText("Only the recorded period is included.")).toBeVisible(); expect(view.container.querySelector(".record-identity-list")).toBeNull();
  });
  it("places a real source action before lengthy assumptions and retains keyboard access to source and close", async () => {
    const user = userEvent.setup(); const view = draw();
    const disclosure = view.getByText("Source documents · 1 source document link").closest("details")!;
    expect(disclosure).not.toHaveAttribute("open");
    expect(view.getByRole("button", { name: "Open example.txt" })).not.toBeVisible();
    const figure = view.getByRole("heading", { name: "Figure details" });
    expect(figure.compareDocumentPosition(disclosure) & Node.DOCUMENT_POSITION_FOLLOWING).toBeTruthy();
    disclosure.querySelector("summary")!.focus(); expect(disclosure.querySelector("summary")).toHaveFocus(); await user.click(disclosure.querySelector("summary")!);
    const source = view.getByRole("button", { name: "Open example.txt" }); const assumptions = view.getByRole("heading", { name: "Current-question assumptions" });
    expect(source.compareDocumentPosition(assumptions) & Node.DOCUMENT_POSITION_FOLLOWING).toBeTruthy();
    source.focus(); expect(source).toHaveFocus(); await user.keyboard("{Enter}"); expect(view.onOpenDocument).toHaveBeenCalledOnce();
    const close = view.getByRole("button", { name: "Close evidence" }); close.focus(); await user.keyboard("{Enter}"); expect(view.onDismiss).toHaveBeenCalledOnce();
  });
  it("leaves legacy figure details and document navigation unchanged", () => {
    const view = draw(false); expect(view.getByText("Measurement type was not supplied by this read.")).toBeVisible();
    fireEvent.click(view.getByRole("button", { name: "Open example.txt" })); expect(view.onOpenDocument).toHaveBeenCalledOnce();
  });
});

it("retains all 42 genuine annual links behind one disclosure while availability and figure remain first", async()=>{
 const answer=accepted_full006;const figure=answer.figures.find((item)=>item.what === "employee retirement contributions · 2024")!;expect(figure.evidenceLinks).toHaveLength(42);
 const data=snapshot();if(data.conversation.state!=="ready")throw new Error("Expected conversation");
 if(data.documents.state!=="ready")throw new Error("Expected documents");data.documents={state:"ready",data:{...data.documents.data,documents:figure.evidenceLinks.map((link)=>({id:link.targetDocumentId,name:link.label,state:"Saved",phaseLabel:"",detail:"",source:"",pages:"",provenance:"",evidenceLinks:[]}))}};
 const original=data.conversation.data.turns[0];data.conversation={state:"ready",data:{...data.conversation.data,turns:[{...original,answer}]}};
 const onOpenDocument=vi.fn();const view=render(<EvidenceDrawer snapshot={data} selection={{figureId:figure.evidenceId!}} onDismiss={vi.fn()} onOpenDocument={onOpenDocument} renderEvidenceBadge={(grade)=><span>{grade.label}</span>} />);
 const disclosure=view.getByText("Source documents · 42 source document links").closest("details")!;
 const heading=view.getByRole("heading",{name:"Figure details"});const availability=view.getByRole("heading",{name:"Numerical receipt available"});
 expect(availability.compareDocumentPosition(heading)&Node.DOCUMENT_POSITION_FOLLOWING).toBeTruthy();expect(heading.compareDocumentPosition(disclosure)&Node.DOCUMENT_POSITION_FOLLOWING).toBeTruthy();
 expect(disclosure).not.toHaveAttribute("open");expect(disclosure.querySelectorAll(".evidence-source-row")).toHaveLength(42);
 const user=userEvent.setup();await user.click(disclosure.querySelector("summary")!);
 const actions=disclosure.querySelectorAll("button");expect(actions).toHaveLength(42);
 for(const [index,action] of [...actions].entries()){expect(action).toBeVisible();fireEvent.click(action);expect(onOpenDocument).toHaveBeenLastCalledWith(figure.evidenceLinks[index]);}
 await user.click(disclosure.querySelector("summary")!);expect(disclosure).not.toHaveAttribute("open");expect(disclosure.querySelectorAll(".evidence-source-row")).toHaveLength(42);
});

it("keeps the supported-receipt absence explanation before all source links without a duplicate",()=>{
 const data=snapshot();if(data.conversation.state!=="ready")throw new Error("Expected conversation");
 const turn=data.conversation.data.turns[0];const answer=turn.answer!;data.conversation={state:"ready",data:{...data.conversation.data,turns:[{...turn,answer:{...answer,figures:answer.figures.map((figure)=>({...figure,receiptState:"unavailable",numericalReceipts:undefined}))}}]}};
 const view=render(<EvidenceDrawer snapshot={data} selection={{figureId:selected}} onDismiss={vi.fn()} onOpenDocument={vi.fn()} renderEvidenceBadge={(grade)=><span>{grade.label}</span>} />);
 const status=view.getByRole("heading",{name:"Numerical receipt unavailable"});const details=view.getByRole("heading",{name:"Figure details"});expect(status.compareDocumentPosition(details)&Node.DOCUMENT_POSITION_FOLLOWING).toBeTruthy();expect(view.getAllByText("This saved answer does not include a supported numerical receipt.")).toHaveLength(1);
});
